-- Hosbah: the "Realtime" section of a git-deployed site (app) — at most one row per app. process is
-- the bare name of a worker declared in the site's cloudy.toml ("reverb" = [processes] "worker:reverb");
-- port is what that process listens on INSIDE its container; path is the URL prefix of the site's
-- hostnames Caddy sends to it ("/" = the whole site, kind custom only — internal/realtime enforces
-- that, and the agent validates process, port and path again). Applies from the next deploy, restart
-- or rollback: the worker has to be started with its port published. Rows go with their app.
ALTER TABLE app_realtime ADD CONSTRAINT app_realtime_kind_check CHECK (kind IN ('reverb', 'socketio', 'ws', 'go', 'custom'));
ALTER TABLE app_realtime ADD CONSTRAINT app_realtime_process_check CHECK (process ~ '^[a-z][a-z0-9_-]{0,30}$');
ALTER TABLE app_realtime ADD CONSTRAINT app_realtime_port_check CHECK (port BETWEEN 1 AND 65535);
ALTER TABLE app_realtime ADD CONSTRAINT app_realtime_path_check CHECK (length(path) BETWEEN 1 AND 100 AND path ~ '^/[A-Za-z0-9._/-]*$' AND (path <> '/' OR kind = 'custom'));
CREATE UNIQUE INDEX app_realtime_app_key ON app_realtime (app_id);
CREATE UNIQUE INDEX app_realtime_id_team_key ON app_realtime (id, team_id);
CREATE INDEX app_realtime_team_idx ON app_realtime (team_id);
